# -*- coding: utf-8 -*-
# 第 11 批（C5）：危險性工作場所審查及檢查辦法（OSH-08）補題
# 對象條文：第10、12、13、14、16、19、21、23、23-1、24 條
# ※ 四個選項刻意寫成相近長度。
B = "OSH-08"
Q = [
(B,"第10條",2,"危險工作場所-乙類評估",
 "乙類工作場所申請審查及檢查所附之資料，應由何人於何時組成評估小組實施評估？",
 ["應由事業單位依作業實際需要，於事前組成評估小組實施評估，其組成及評估準用甲類工作場所之規定","應由檢查機構於受理申請後指派專家學者組成評估小組實施評估，所需費用由申請之事業單位負擔","應由中央主管機關認可之技術顧問公司單獨組成評估小組實施評估，事業單位人員一律不得參與","應由當地主管機關會同消防機關組成評估小組實施評估，並於評估後函知事業單位配合辦理改善"],"a",
 "第10條：第9條資料事業單位應依作業實際需要，於事前組成評估小組實施評估；前項評估小組之組成及評估，準用第6條之規定。第9條：乙類工作場所應檢附安全衛生管理基本資料、製程安全評估報告書、製程修改安全計畫、緊急應變計畫及稽核管理計畫各三份。",
 "Who must form the assessment team for a Class B workplace's application documents, and when?",
 ["The undertaking itself forms an assessment team in advance as the work actually requires, its composition and assessment following the rules for Class A workplaces","The inspection agency appoints experts and scholars to form the team after accepting the application, the cost of it being borne by the applicant undertaking","A technical consultancy recognised by the central competent authority forms the team alone, and the undertaking's own personnel may take no part in it at all","The local competent authority together with the fire authority forms the team and, after assessing, informs the undertaking of the improvements to be made"],
 "Article 10; see Articles 6 and 9."),

(B,"第10條",3,"危險工作場所-評估小組成員",
 "乙類工作場所評估小組準用第六條規定，其成員應包括哪些人員？",
 ["工作場所負責人、製程安全評估人員、依職業安全衛生管理辦法設置之職業安全衛生人員、工作場所作業主管、熟悉該場所作業之勞工","工作場所負責人、當地勞動檢查機構之檢查員、地方主管機關指派之代表、消防主管機關人員、環境保護主管機關指派之技術人員","事業單位董事長、財務主管、法務人員、人力資源主管、公共關係主管及該工作場所所在地之里長與地方民意代表各一人以上","原設備製造廠之工程師、設備供應商業務代表、保險公司理賠人員、工程顧問公司之估價人員及承攬商之現場工地主任"],"a",
 "第6條第1項：評估小組成員為工作場所負責人、曾受國內外製程安全評估專業訓練或具製程安全評估專業能力並經中央主管機關認可者（製程安全評估人員）、依職業安全衛生管理辦法設置之職業安全衛生人員、工作場所作業主管、熟悉該場所作業之勞工。第6條第4項：實施評估之過程及結果，應予記錄。第10條第2項：乙類工作場所之評估小組組成及評估準用之。",
 "Applying Article 6, who must sit on a Class B workplace's assessment team?",
 ["The head of the workplace, a process safety assessor, the safety and health personnel appointed under the safety management regulations, the work supervisor, and a worker familiar with the operations","The head of the workplace, an inspector from the local labor inspection agency, a representative of the local competent authority, a fire services officer, and a technician of the environmental authority","The chairman of the undertaking, the finance head, a legal officer, the human resources head, the public relations head, and at least one local borough chief and local councillor","An engineer of the original equipment maker, the supplier's sales representative, an insurance claims officer, a consultancy's cost estimator, and the contractor's own site manager"],
 "Articles 6 and 10."),

(B,"第12條",2,"危險工作場所-乙類重評",
 "乙類工作場所經審查及檢查合格後，事業單位應於何時依何資料重新評估？",
 ["應於製程修改時或至少每五年，依第九條檢附之資料重新評估一次，為必要之更新並記錄之","應於製程修改時或至少每三年，依第九條檢附之資料重新評估一次，並報請檢查機構備查","應於製程修改時或至少每十年，依第五條檢附之資料重新評估一次，並報請中央主管機關核准","應僅於發生重大職業災害後重新評估一次，平時無須定期辦理重新評估或資料之更新與記錄"],"a",
 "第12條：事業單位對經檢查機構審查及檢查合格之乙類工作場所，應於製程修改時或至少每五年依第9條檢附之資料重新評估一次，為必要之更新並記錄之。第8條：甲類工作場所亦應於製程修改時或至少每五年重新評估第5條檢附之資料，為必要之更新及記錄，並報請檢查機構備查。",
 "When and on what basis must a Class B workplace be re-assessed after passing review and inspection?",
 ["On any process modification, or at least once every five years, using the Article 9 documents, with necessary updating and a record kept of it","On any process modification, or at least once every three years, using the Article 9 documents, and the result filed with the inspection agency","On any process modification, or at least once every ten years, using the Article 5 documents, subject to approval by the central competent authority","Only after a major occupational accident has occurred, no periodic re-assessment or updating and recording of the documents being needed otherwise"],
 "Article 12; cf. Article 8."),

(B,"第12條",2,"危險工作場所-重評準用",
 "乙類工作場所之重新評估，其評估小組之組成及評估方式應如何辦理？與甲類有何不同？",
 ["重新評估準用第六條之規定；與甲類不同者，甲類重新評估後尚應報請檢查機構備查，乙類則僅須為必要之更新並記錄","重新評估準用第十八條之規定；與甲類不同者，乙類重新評估後應報請中央主管機關核准，甲類則僅須自行記錄留存","重新評估得由事業單位自行決定方式；與甲類不同者，乙類重新評估無須組成評估小組，僅須由工作場所負責人簽認","重新評估應由檢查機構指派人員辦理；與甲類不同者，乙類重新評估之費用由檢查機構負擔，甲類則由事業單位負擔"],"a",
 "第12條第2項：前項重新評估，準用第6條之規定，亦即仍應由工作場所負責人、製程安全評估人員、職業安全衛生人員、作業主管及熟悉該場所作業之勞工組成評估小組，並記錄評估過程及結果。第8條第1項：甲類工作場所重新評估後，尚應報請檢查機構備查。",
 "How is a Class B workplace's re-assessment team formed, and how does this differ from Class A?",
 ["The re-assessment follows Article 6; unlike Class A, which must also file the result with the inspection agency, Class B need only make the necessary updates and keep a record","The re-assessment follows Article 18; unlike Class A, which merely keeps its own record, Class B must obtain the approval of the central competent authority for the result","The undertaking may decide the method itself; unlike Class A, Class B needs no assessment team at all and the head of the workplace need only sign off on the result","The inspection agency assigns personnel to do it; unlike Class A, where the undertaking pays, the cost of a Class B re-assessment is borne by the inspection agency"],
 "Article 12, Paragraph 2; cf. Article 8."),

(B,"第13條",2,"危險工作場所-丙類申請",
 "事業單位向檢查機構申請審查及檢查丙類工作場所時，應填具何種申請書並檢附何資料？",
 ["應填具格式三申請書，並檢附第九條各款規定之應審查資料各三份","應填具格式一申請書，並檢附製程安全評估定期實施辦法所定附表各二份","應填具格式四申請書，並檢附施工計畫書及施工安全評估報告書各三份","應填具格式二申請書，並檢附施工安全評估人員之簽章文件各一份"],"a",
 "第13條：事業單位向檢查機構申請審查及檢查丙類工作場所，應填具申請書（如格式三），並檢附第9條各款規定之應審查資料各三份。第2條第3款：丙類指蒸汽鍋爐之傳熱面積在五百平方公尺以上，或高壓氣體類壓力容器一日之冷凍能力在一百五十公噸以上，或處理能力達一千立方公尺以上之氧氣、有毒性及可燃性高壓氣體等工作場所。",
 "Which form and documents are used to apply for review and inspection of a Class C workplace?",
 ["Application form 3, together with three copies each of the documents listed in Article 9","Application form 1, together with two copies each of the appendices under the process rules","Application form 4, together with three copies each of the construction and safety reports","Application form 2, together with one copy of the signed papers of the safety assessor"],
 "Article 13; see Articles 2 and 9."),

(B,"第13條",3,"危險工作場所-應審查資料",
 "丙類工作場所所應檢附之第九條各款應審查資料，其內容為何？",
 ["安全衛生管理基本資料、製程安全評估報告書、製程修改安全計畫、緊急應變計畫、稽核管理計畫","安全衛生管理基本資料、施工計畫書、施工安全評估報告書、專任工程人員簽章文件、交通維持計畫","製程安全評估定期實施辦法所定附表一至附表十四、環境影響說明書、消防安全設備圖說、放流水檢驗報告","公司登記證明文件、工廠登記證影本、勞工保險投保名冊、教育訓練紀錄、健康檢查紀錄、承攬管理計畫"],"a",
 "第9條：乙類工作場所應檢附安全衛生管理基本資料（附件一）、製程安全評估報告書（附件二）、製程修改安全計畫（附件三）、緊急應變計畫（附件四）、稽核管理計畫（附件五）各三份；第13條規定丙類工作場所亦檢附同條各款規定之應審查資料各三份。第15條：檢查機構於審查後，應對一般高壓氣體製造設施、液化石油氣製造設施、冷凍用高壓氣體製造設施、加氣站製造設施及鍋爐設施實施檢查。",
 "What are the Article 9 documents that a Class C workplace must attach?",
 ["Basic safety and health management data, a process safety assessment report, a process modification safety plan, an emergency response plan and an audit management plan","Basic safety and health management data, a construction plan, a construction safety assessment report, the signed papers of the resident engineer and a traffic maintenance plan","Appendices 1 to 14 under the Regulations for Periodic Process Safety Assessment, an environmental impact statement, fire safety drawings and effluent testing reports","The company registration documents, a copy of the factory registration, the labor insurance roster, training records, health examination records and a contractor management plan"],
 "Articles 9 and 13; cf. Article 15."),

(B,"第14條",2,"危險工作場所-丙類評估",
 "丙類工作場所申請審查及檢查所附之資料，其評估小組應如何組成？",
 ["應由事業單位依作業實際需要，於事前組成評估小組實施評估，其組成及評估準用甲類工作場所之規定","應由檢查機構於受理申請後指派專家學者組成評估小組實施評估，所需費用由申請之該事業單位負擔","應由高壓氣體或鍋爐設備之原製造廠單獨組成評估小組實施評估，事業單位人員及勞工均不得參與其中","應由當地主管機關會同消防及環境保護機關組成評估小組實施評估，並於評估後函知事業單位配合改善"],"a",
 "第14條：第13條資料事業單位應依作業實際需要，於事前組成評估小組實施評估；前項評估小組之組成及評估，準用第6條之規定。第6條第4項：實施評估之過程及結果，應予記錄。第22條：檢查機構實施審查、檢查時，製程安全評估小組成員應列席說明。",
 "How must the assessment team for a Class C workplace's application documents be formed?",
 ["The undertaking itself forms an assessment team in advance as the work actually requires, its composition and assessment following the rules for Class A workplaces","The inspection agency appoints experts and scholars to form the team after accepting the application, the cost of it being borne by that applicant undertaking","The original maker of the high pressure gas or boiler plant forms the team alone, and neither the undertaking's own staff nor its workers may take any part in it","The local competent authority with the fire and environmental authorities forms the team and, after assessing, tells the undertaking what improvements to make"],
 "Article 14; see Articles 6 and 22."),

(B,"第14條",3,"危險工作場所-技師替代",
 "事業單位未置製程安全評估人員時，準用第六條規定，得由哪些人員擔任？",
 ["得以在國內完成製程安全評估人員訓練之工業安全技師，並具化學工程、職業衛生、機械工程或電機工程技師之一者任之","得以未曾受訓之土木工程技師或結構工程技師任之，並得由該工作場所負責人指定之現場作業主管一併兼任其職務","得以在國內完成施工安全評估人員訓練之建築師，並具大地工程或水利工程技師之一者任之，無須具備工業安全技師","得以事業單位人力資源主管或法務人員任之，惟應事先報請當地勞動檢查機構同意，並於評估報告書內載明其資格"],"a",
 "第6條第2項：事業單位未置製程安全評估人員者，得以在國內完成製程安全評估人員訓練之下列執業技師任之：一、工業安全技師及化學工程技師、職業衛生技師、機械工程技師、電機工程技師之一；二、工程技術顧問公司僱用之工業安全技師及前款各目所定技師之一。第3項：兼具工業安全技師資格及前項各目技師資格之一者，得為同一人。第14條第2項：丙類工作場所之評估準用之。",
 "Where no process safety assessor is employed, who may act instead under Article 6?",
 ["An industrial safety engineer who has completed domestic process safety assessor training, together with a chemical, occupational hygiene, mechanical or electrical engineer","An untrained civil engineer or structural engineer, and the head of the workplace may also appoint a site work supervisor to hold the post concurrently with it","An architect who has completed domestic construction safety assessor training, together with a geotechnical or hydraulic engineer, with no industrial safety engineer needed","The undertaking's human resources head or legal officer, provided the local labor inspection agency agrees beforehand and the qualification is stated in the report"],
 "Article 6, Paragraphs 2-3; Article 14."),

(B,"第16條",2,"危險工作場所-丙類重評",
 "丙類工作場所經審查及檢查合格後，事業單位應於何時依何資料重新評估？",
 ["應於製程修改時或至少每五年，依第十三條檢附之資料重新評估一次，為必要之更新並記錄之","應於製程修改時或至少每三年，依第十三條檢附之資料重新評估一次，並報請檢查機構備查","應於製程修改時或至少每十年，依第九條檢附之資料重新評估一次，並報請中央主管機關核准","應僅於高壓氣體設備發生洩漏事故後重新評估，平時無須定期辦理重新評估或資料之更新"],"a",
 "第16條：事業單位對經檢查機構審查及檢查合格之丙類工作場所，應於製程修改時或至少每五年依第13條檢附之資料重新評估一次，為必要之更新並記錄之。第12條就乙類工作場所定有相同之五年重新評估規定，惟其依據資料為第9條所附之資料。",
 "When and on what basis must a Class C workplace be re-assessed after it passes?",
 ["On any process modification, or at least once every five years, using the Article 13 documents, with necessary updating and a record kept of it","On any process modification, or at least once every three years, using the Article 13 documents, and the result filed with the inspection agency","On any process modification, or at least once every ten years, using the Article 9 documents, subject to approval by the central competent authority","Only after a leak from the high pressure gas plant has occurred, no periodic re-assessment or updating of the documents being needed otherwise"],
 "Article 16; cf. Article 12."),

(B,"第16條",2,"危險工作場所-丙類重評準用",
 "丙類工作場所之重新評估，其評估之組成及過程應如何辦理？",
 ["重新評估準用第六條之規定，仍應組成評估小組實施評估，並將評估之過程及結果予以記錄","重新評估準用第十八條之規定，應由專任工程人員及開業建築師組成施工安全評估小組實施之","重新評估得由工作場所負責人一人逕行辦理，無須組成評估小組，亦無須記錄其過程及結果","重新評估應由檢查機構指派檢查員會同專家學者辦理，事業單位僅須配合提供資料及說明即可"],"a",
 "第16條第2項：前項重新評估，準用第6條之規定，故仍應由工作場所負責人、製程安全評估人員、職業安全衛生人員、工作場所作業主管及熟悉該場所作業之勞工組成評估小組實施評估，並依第6條第4項將實施評估之過程及結果予以記錄。第18條所定施工安全評估小組，則適用於丁類工作場所。",
 "How is the re-assessment of a Class C workplace to be organised and recorded?",
 ["It follows Article 6: an assessment team must still be formed to carry it out, and the process and results of the assessment must be recorded","It follows Article 18: a construction safety assessment team of resident engineers and licensed architects must be formed to carry it out","The head of the workplace may carry it out alone with no assessment team, and neither the process nor the results need be recorded","The inspection agency assigns inspectors and outside experts to do it, the undertaking merely supplying the data and explanations needed"],
 "Article 16, Paragraph 2; cf. Articles 6 and 18."),

(B,"第19條",2,"危險工作場所-丁類審查",
 "丁類工作場所之審查，檢查機構得否實施現場檢查？審查結果應於何時通知？",
 ["檢查機構認有必要時得前往該工作場所實施檢查；審查結果應於受理申請後三十日內以書面通知事業單位","檢查機構應一律前往該工作場所實施檢查；審查結果應於受理申請後四十五日內以書面通知該事業單位","檢查機構不得前往該工作場所實施任何檢查；審查結果應於受理申請後六十日內以書面通知該事業單位","檢查機構得委由事業單位自行檢查後回報；審查結果應於受理申請後九十日內以書面通知該事業單位"],"a",
 "第19條：第17條之審查，檢查機構認有必要時，得前往該工作場所實施檢查；第17條審查之結果，檢查機構應於受理申請後三十日內，以書面通知事業單位。甲類工作場所之審查結果亦為三十日內通知（第7條）；乙類、丙類之審查及檢查結果則為四十五日內（第11條、第15條）。第4條：甲類、丁類應於使勞工作業三十日前申請審查，乙類、丙類應於四十五日前申請審查及檢查。",
 "May the agency inspect a Class D workplace on site, and when must the result be notified?",
 ["It may go to the workplace and inspect where it considers this necessary; the review result must be notified in writing within thirty days of accepting the application","It must always go to the workplace and inspect it; the review result must be notified in writing within forty-five days of accepting the application it received","It may not go to the workplace and inspect it at all; the review result must be notified in writing within sixty days of accepting the application it received","It may leave the undertaking to inspect and report back; the review result must be notified in writing within ninety days of accepting the application"],
 "Article 19; cf. Articles 4, 7, 11 and 15."),

(B,"第19條",2,"危險工作場所-通知例外",
 "檢查機構應於受理申請後三十日內書面通知丁類工作場所審查結果，其例外情形為何？",
 ["但可歸責於事業單位者，不在此限","但經事業單位同意者，得延長為六十日","但遇天然災害者，得展延一次為九十日","但申請案件過多時，得由檢查機構逕行順延"],"a",
 "第19條第2項：第17條審查之結果，檢查機構應於受理申請後三十日內，以書面通知事業單位；但可歸責於事業單位者，不在此限。第7條（甲類）、第11條（乙類）、第15條（丙類）之通知期限亦均定有相同之但書。第17條第4項：對於工程內容較複雜、工期較長、施工條件變動性較大等特殊狀況之營造工程，得報經檢查機構同意後分段申請審查。",
 "What is the exception to notifying a Class D review result within thirty days?",
 ["Unless the delay is attributable to the undertaking itself","Unless the undertaking agrees, when it may be extended to sixty days","Unless a natural disaster occurs, when one extension to ninety days is allowed","Unless applications are too numerous, when the agency may simply defer it"],
 "Article 19, Paragraph 2."),

(B,"第21條",1,"危險工作場所-專家協助",
 "檢查機構為執行危險性工作場所審查、檢查，得如何借助外部專業？",
 ["得就個案邀請專家學者協助之","得將全部審查檢查業務委外辦理","得要求事業單位自行聘請專家代審","得逕行指定特定顧問公司獨家承辦"],"a",
 "第21條：檢查機構為執行危險性工作場所審查、檢查，得就個案邀請專家學者協助之。第22條：檢查機構實施危險性工作場所審查、檢查時，製程安全評估小組、施工安全評估小組成員應列席說明。第23條：實施審查、檢查時，應摘要記錄過程及決議等事項。",
 "How may an inspection agency draw on outside expertise for these reviews and inspections?",
 ["It may invite experts and scholars to assist on a case-by-case basis","It may outsource the whole of the review and inspection business","It may require the undertaking to hire experts to review on its behalf","It may designate one particular consultancy as the sole contractor"],
 "Article 21; cf. Articles 22-23."),

(B,"第23條",1,"危險工作場所-紀錄",
 "檢查機構實施危險性工作場所審查、檢查時，對於過程及決議應如何處理？",
 ["應摘要記錄過程及決議等事項","應全程錄音錄影並公開於資訊網站","應由事業單位自行記錄後報請備查","無須作成任何形式之書面紀錄留存"],"a",
 "第23條：檢查機構實施危險性工作場所審查、檢查時，應摘要記錄過程及決議等事項。第22條：實施審查、檢查時，製程安全評估小組、施工安全評估小組成員應列席說明。第21條：得就個案邀請專家學者協助之。",
 "How must the agency deal with the process and resolutions of a dangerous workplace review?",
 ["It must keep a summary record of the process and the resolutions","It must record audio and video throughout and publish it online","The undertaking itself keeps the record and files it afterwards","No written record of any kind needs to be made of the process"],
 "Article 23."),

(B,"第23條之1",2,"危險工作場所-爆竹煙火",
 "爆竹煙火工廠向檢查機構申請審查或檢查時，應另檢附何種文件？",
 ["應檢附由爆竹煙火管理條例主管機關核發之製造許可文件影本","應檢附由消防主管機關核發之公共危險物品儲存許可文件影本","應檢附由環境保護主管機關核發之固定污染源操作許可證影本","應檢附由建築主管機關核發之工廠建築物使用執照文件影本"],"a",
 "第23條之1：爆竹煙火工廠向檢查機構申請審查或檢查時，應檢附由爆竹煙火管理條例主管機關核發之製造許可文件影本。第2條第2款第2目：乙類工作場所包括利用氯酸鹽類、過氯酸鹽類、硝酸鹽類、硫、硫化物、磷化物、木炭粉、金屬粉末及其他原料製造爆竹煙火類物品之爆竹煙火工廠。",
 "What extra document must a fireworks factory attach when applying for review or inspection?",
 ["A copy of the manufacturing permit issued by the authority under the Fireworks and Firecrackers Act","A copy of the storage permit for public hazardous substances issued by the fire services authority","A copy of the stationary source operating permit issued by the environmental protection authority","A copy of the use permit for the factory building issued by the building administration authority"],
 "Article 23-1; see Article 2."),

(B,"第23條之1",2,"危險工作場所-爆竹煙火分類",
 "製造爆竹煙火類物品之爆竹煙火工廠，屬何類危險性工作場所？其申請期限為何？",
 ["屬乙類工作場所，應於使勞工作業四十五日前向檢查機構申請審查及檢查","屬甲類工作場所，應於使勞工作業三十日前向檢查機構申請審查及檢查","屬丙類工作場所，應於使勞工作業三十日前向檢查機構申請審查及檢查","屬丁類工作場所，應於使勞工作業四十五日前向檢查機構申請審查及檢查"],"a",
 "第2條第2款第2目：乙類工作場所包括利用氯酸鹽類、過氯酸鹽類、硝酸鹽類、硫、硫化物、磷化物、木炭粉、金屬粉末及其他原料製造爆竹煙火類物品之爆竹煙火工廠。第4條第2項：事業單位應於乙類、丙類工作場所使勞工作業四十五日前，向檢查機構申請審查及檢查。第23條之1：爆竹煙火工廠申請時應檢附製造許可文件影本。",
 "Which class of dangerous workplace is a fireworks factory, and what is its application deadline?",
 ["Class B, applying for review and inspection forty-five days before workers are put to work there","Class A, applying for review and inspection thirty days before workers are put to work there","Class C, applying for review and inspection thirty days before workers are put to work there","Class D, applying for review and inspection forty-five days before workers are put to work"],
 "Articles 2, 4 and 23-1."),

(B,"第24條",1,"危險工作場所-施行日期",
 "危險性工作場所審查及檢查辦法之施行日期為何？",
 ["本辦法自發布日施行","本辦法自發布後一年施行","本辦法自發布後六個月施行","本辦法自次年一月一日起施行"],"a",
 "第24條：本辦法自發布日施行。第1條：本辦法依勞動檢查法第二十六條第二項規定訂定。第4條：事業單位應於甲類、丁類工作場所使勞工作業三十日前向當地勞動檢查機構申請審查；乙類、丙類工作場所則應於使勞工作業四十五日前申請審查及檢查。",
 "When do the Regulations for Review and Inspection of Dangerous Workplaces take effect?",
 ["They take effect on the day they are promulgated","They take effect one year after they are promulgated","They take effect six months after they are promulgated","They take effect on 1 January of the following year"],
 "Article 24."),
]
